const http = require("http");

function echapperHTML(texte) {
  return String(texte)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

const serveur = http.createServer((req, res) => {
  const nom = new URL(req.url, "http://localhost").searchParams.get("nom") || "visiteur";
  res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
  res.end("<p>Bonjour " + echapperHTML(nom) + "</p>");
});

const COURRIEL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validerInscription(d) {
  const erreurs = [];
  if (typeof d.nom !== "string" || d.nom.trim().length < 2 || d.nom.length > 50) erreurs.push("nom");
  if (typeof d.courriel !== "string" || !COURRIEL.test(d.courriel)) erreurs.push("courriel");
  if (!Number.isInteger(d.age) || d.age < 13 || d.age > 120) erreurs.push("age");
  return erreurs;
}
